import React from "react";

function RatingStars({ value = 0, onChange = () => {}, max = 5 }) {

  const stars = Array.from({ length: max }, (_, i) => i + 1);
  return (
    <div className="stars">
      {stars.map((n) => (
        <button
          key={n}
          type="button"
          // role="radio"
          // aria-checked={n === value}
          onClick={() => onChange(n)}
        >
          {n <= value ? "*" : "-"}
        </button>
      ))}
      <span style={{ marginLeft: 8 }}>{value}/{max}</span>
    </div>
  );
}

export default RatingStars;
